 "content": "def transform(grid):
    """Demonstrated transformation: marker-aligned lines recolor crossed cells/objects.

    This implementation was not verified against all received demonstrations;
    retained only as a best-effort candidate for this completed task.
    """
    h, w = len(grid), len(grid[0])
    rows = {r for r in range(h) for c in range(w) if grid[r][c] == 1}
    cols = {c for r in range(h) for c in range(w) if grid[r][c] == 1}
    out = [row[:] for row in grid]
    for r in rows:
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = 1
    for c in cols:
        for r in range(h):
            if out[r][c] == 0:
                out[r][c] = 1
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                x, y = stack.pop()
                component.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if any(x in rows or y in cols for x, y in component):
                for x, y in component:
                    out[x][y] = 1
    return out
